mapper.select:
select id, title, method, request_method, request_url, request_param,
       oper_user_id, oper_user_name, oper_ip, oper_time, cost_time, status, error_msg
from sys_oper_log


        and title like concat('%', #{title}, '%')


        and oper_user_name like concat('%', #{operUserName}, '%')


        and status = #{status}


        and oper_time >= #{begin}


        and oper_time <= #{end}


order by oper_time desc, id desc
